-- One simple main service: Visa Consultancy (PKR 15,000, fixed) = country suggestion + document review + visa file preparation.
-- Existing services stay (call consultancy, document review, ...). CV / resume / cover letter / portfolio / social profile
-- / SOP services are added INACTIVE with no fee; the owner sets the fee and activates each.
insert into public.services (slug,title,summary,description,scope,inclusions,exclusions,duration_minutes,fee_pkr,fee_is_starting_price,fee_needs_review,is_active,refund_terms,sort_order) values
('visa-consultancy', 'Visa Consultancy (Complete Package)', 'We suggest the right country for you, review your documents and get your visa file ready, for one fixed fee.', 'A complete guided service. We understand your profile and goal, suggest suitable countries, review the documents you upload against the official checklist and help you prepare a complete visa file. You remain the applicant and the final decision is always made by the relevant authority.', 'Country suggestion, document review and visa file preparation.', array['Country suggestion based on your profile, budget and goal', 'Review of your documents against the official checklist', 'Written list of gaps and corrections', 'Visa file prepared and organised for submission', 'Consultant support through WhatsApp or call during the process']::text[], array['Government, embassy, biometric or university fees', 'Legal advice or representation before an authority', 'Any guarantee of a visa or immigration outcome']::text[], null, 15000, false, false, true, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 1)
on conflict (slug) do update set fee_pkr = 15000, fee_is_starting_price = false, fee_needs_review = false, is_active = true, sort_order = 1;

update public.services set title = 'Call Consultancy', summary = 'A one-to-one online call to understand your options and the general process.', sort_order = 2 where slug = 'visa-guidance-session';
update public.services set sort_order = 3 where slug = 'document-review';
update public.services set sort_order = 4 where slug = 'application-assistance';

insert into public.services (slug,title,summary,description,scope,inclusions,exclusions,duration_minutes,fee_pkr,fee_is_starting_price,fee_needs_review,is_active,refund_terms,sort_order) values
('resume-cv-writing', 'Resume / CV Writing', 'A clear, professional resume or CV prepared from your real experience.', 'We prepare or rewrite your resume/CV in a format suited to study, work or visa applications. Everything is based on the facts you give us; we never add false experience.', 'Resume / CV preparation.', array['Professional layout', 'Content based only on your real background', 'One round of revisions']::text[], array['Any guarantee of a job, admission or visa', 'Fabricated qualifications or experience']::text[], null, 0, false, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 13),
('cover-letter-writing', 'Cover Letter Writing', 'A cover letter tailored to your application.', 'A personal, honest cover letter for a job, university or visa application, written from the details you provide.', 'Cover letter preparation.', array['Tailored to your target', 'One round of revisions']::text[], array['Any guarantee of a job, admission or visa']::text[], null, 0, false, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 14),
('portfolio-design', 'Portfolio', 'A neat portfolio that presents your work and projects.', 'We organise and present your work (design, writing, projects, research) as a clean portfolio for applications.', 'Portfolio preparation.', array['Layout and organisation of your own work', 'One round of revisions']::text[], array['Creating work on your behalf that you present as your own']::text[], null, 0, false, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 15),
('social-media-profiles', 'Social Media & Professional Profiles', 'Review and improve your LinkedIn and other professional profiles.', 'We review your professional and social profiles and suggest clear, honest improvements so they are consistent with your application.', 'Profile review and improvement suggestions.', array['Review of your professional profiles', 'Written suggestions', 'Consistency check with your application details']::text[], array['Managing your accounts', 'Any guarantee of an outcome']::text[], null, 0, false, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 16),
('sop-motivation-letter', 'SOP / Motivation Letter', 'Help writing a clear statement of purpose or motivation letter.', 'We help you structure and write your own statement of purpose or motivation letter, based on your real goals and background.', 'SOP / motivation letter preparation.', array['Outline and drafting support', 'Feedback on your draft', 'One round of revisions']::text[], array['Writing false or copied content', 'Any guarantee of admission or visa']::text[], null, 0, false, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy.', 17)
on conflict (slug) do nothing;
